import java.util.*;

public class Main {
    class MinStack {
        List<Integer> stack = new ArrayList<>();

        void push(int val) { stack.add(val); }
        void pop() { stack.remove(stack.size() - 1); }
        int top() { return stack.get(stack.size() - 1); }

        int getMin() {
            int min = stack.get(0);
            for (int v : stack) min = Math.min(min, v);                            // O(n) scan every time the minimum is asked for
            return min;
        }
    }

    public static void main(String[] args) {
        MinStack ms = new MinStack();
        ms.push(-2);
        ms.push(0);
        ms.push(-3);
        System.out.println(ms.getMin());
        ms.pop();
        System.out.println(ms.top());
        System.out.println(ms.getMin());
    }
}

