import java.util.*;

public class Main {
    class MinStack {
        Deque<Integer> stack = new ArrayDeque<>();
        Deque<Integer> minStack = new ArrayDeque<>();                                 // minStack's top = the minimum among everything currently in stack

        void push(int val) {
            stack.push(val);
            int currentMin = minStack.isEmpty() ? val : Math.min(minStack.peek(), val);
            minStack.push(currentMin);                                                    // every push also records the min "so far, up to here"
        }

        void pop() {
            stack.pop();
            minStack.pop();                                                               // popping BOTH together keeps them perfectly in sync
        }

        int top() { return stack.peek(); }

        int getMin() { return minStack.peek(); }                                          // O(1): always just the top of minStack
    }

    public static void main(String[] args) {
        MinStack ms = new MinStack();
        ms.push(-2);
        ms.push(0);
        ms.push(-3);
        System.out.println(ms.getMin());
        ms.pop();
        System.out.println(ms.top());
        System.out.println(ms.getMin());
    }
}

